import{t as e}from"./jsx-runtime-lw2jiZar.js";import{M as t,N as n,O as r,P as i,S as a,b as o,k as s,l as c,n as l,o as u,p as d,t as f,u as p,x as m}from"./shared-DoR5oW6-.js";import{t as h}from"./CodeEditor-BZlrvoTL.js";var g=e();function _({module:e}){return(0,g.jsxs)(n,{children:[(0,g.jsx)(t,{chip:e??`Блок 3 · Функции и инструменты`,title:`15.1. Передаём проект дальше`,intro:`Проверим опубликованную основу StudyHub в отдельной копии и выясним, что именно получает следующий блок.`}),(0,g.jsxs)(i,{number:`00`,title:`От своего проекта к проверенной передаче`,children:[(0,g.jsx)(r,{children:`Проверим, какую опубликованную версию получает отдельная копия и как продолжить работу с неё.`}),(0,g.jsx)(s,{variant:`connected`,items:[{title:`Точка старта`,description:`Найдите в своём main.py четыре функции и короткое демо; затем сверим remote, ветку и commit.`},{title:`Новый вопрос`,description:`Как отличить сохранённую публикацию от последней правки в папке и какую именно ветку получит clone?`},{title:`Результат`,description:`Проверочная копия получает выбранную версию; мы запускаем её и проверяем четыре функции.`}]}),(0,g.jsx)(`p`,{children:`Найдите в основном каталоге main.py с функциями normalize_title, create_task, format_task и calculate_study_minutes. По шагам ниже сверьте origin, ветку и полный SHA с версией, которую передаёте дальше. Если нужную ветку или commit определить не удаётся, остановитесь до клонирования.`})]}),(0,g.jsxs)(i,{number:`01`,title:`Что получает clone`,children:[(0,g.jsx)(`p`,{children:`В рабочей папке могут находиться три разных состояния. Текст файла после сохранения виден на диске, но может ещё не входить в commit. Commit сохраняет локальный снимок файлов в истории. Push отправляет выбранные локальные commit в конкретную ветку remote, то есть удалённого репозитория. Команда clone создаёт новую рабочую папку из опубликованной истории remote. Поэтому она не забирает незакоммиченный текст и локальные игнорируемые файлы.`}),(0,g.jsx)(`p`,{children:`Аналогия с отправкой чертежа: пока исправления только на нашем столе, получатель их не видит. Мы сохраняем названную версию, помещаем её в общий архив, затем другой человек получает опубликованный экземпляр. Граница аналогии важна: commit и push в Git являются отдельными действиями, а в истории остаются версии и их порядок. Успешный запуск из основной папки сообщает только об этой папке. Запуск clone проверяет файлы, которые действительно добрались до публикации.`}),(0,g.jsx)(d,{prompt:`Сопоставьте состояние и его роль перед передачей.`,leftTitle:`Состояние`,rightTitle:`Что оно означает`,pairs:[{left:`Рабочие файлы`,right:`Текущий текст в основной папке, в том числе незаписанная в историю правка`},{left:`Локальный commit`,right:`Сохранённый снимок в истории этого репозитория`},{left:`Remote branch`,right:`Опубликованная история выбранной ветки`},{left:`Clone`,right:`Новая рабочая папка, полученная из опубликованной истории`}],explanation:`Новая копия строится от remote. Незакоммиченное изменение остаётся только в рабочей папке автора.`}),(0,g.jsx)(a,{statement:`В main.py есть новая правка, но мы ещё не создали для неё commit. Clone из remote автоматически получит эту правку.`,isTrue:!1,explanation:`Clone получает опубликованную историю. Правка попадёт туда после сохранения в commit и публикации нужной ветки.`})]}),(0,g.jsxs)(i,{number:`02`,title:`Два каталога и выбранная ветка`,children:[(0,g.jsx)(`p`,{children:`Основной clone остаётся местом разработки. Проверочная копия нужна, чтобы запустить опубликованную версию из другого каталога; правки в ней не продолжают основную историю автоматически. Это похоже на две рабочие тетради, открытые на разных столах: пометка в одной не появляется в другой, пока мы явно не перенесём обновление. Поэтому перед каждой командой мы смотрим путь терминала, а не ориентируемся на название окна или папки.`}),(0,g.jsx)(`p`,{children:`У репозитория есть ветка по умолчанию. Обычный git clone выбирает её. Если checkpoint B3 опубликован в другой ветке, укажем ровно то имя, которое видно в списке веток своего репозитория. Не угадываем main: имя по умолчанию бывает другим. Перед clone проверяем, что целевой соседний каталог свободен. Если уже есть правильная проверочная копия, используем её, а не создаём вторую и не удаляем прежнюю.`}),(0,g.jsx)(`p`,{children:`Clone получает верх выбранной ветки, а не произвольный commit из её истории. Поэтому перед клонированием убеждаемся, что именно текущая версия этой ветки является нужной основой B3. Если ветка уже продвинулась к более позднему Planner или полный SHA не совпал с передаваемым checkpoint, не запускаем эту копию как B3. Сначала уточняем, какая опубликованная версия должна перейти дальше.`}),(0,g.jsx)(h,{caption:`Шаблон команды для ветки, в которой опубликован checkpoint`,code:`git clone --branch "ИМЯ_ВЕТКИ" "URL_СВОЕГО_REMOTE" "ПУТЬ_К_СВОБОДНОЙ_ПАПКЕ"`}),(0,g.jsx)(`p`,{children:`Это шаблон, а не готовая команда: каждое значение в кавычках заменяем данными своего проекта. Для ветки по умолчанию часть --branch не нужна. Clone сам связывает полученную копию с remote под именем origin. Повторно выполнять git init в этой папке не нужно: история уже пришла из репозитория.`}),(0,g.jsx)(o,{question:`В списке веток своего проекта checkpoint находится в ветке handoff-b3, а ветка по умолчанию называется main. Какую команду выбрать для новой свободной папки?`,options:[`git clone URL ПАПКА`,`git clone --branch handoff-b3 URL ПАПКА`,`git init ПАПКА`],correctIndex:1,explanation:`Нужно запросить фактическую ветку checkpoint. Обычный clone выбрал бы main, а init создал бы новую историю вместо копии опубликованного проекта.`})]}),(0,g.jsxs)(i,{number:`03`,title:`Сверяем, что именно проверяем`,children:[(0,g.jsx)(`p`,{children:`До клонирования свяжем четыре факта: путь основного проекта, адрес его origin, имя текущей ветки и полный идентификатор commit. В PowerShell git status --short показывает незакоммиченные изменения, remote get-url origin выводит адрес remote, а branch --show-current показывает активную ветку. Команда rev-parse HEAD печатает полный идентификатор текущего commit. HEAD здесь обозначает выбранный сейчас commit.`}),(0,g.jsx)(h,{caption:`Читаем состояние основного репозитория`,code:[`git status --short`,`git remote get-url origin`,`git branch --show-current`,`git rev-parse HEAD`].join(`
`)}),(0,g.jsx)(`p`,{children:`Теперь в своём репозитории найдём ветку, где опубликован результат блока 3, и сверим полный SHA на странице remote с локальной историей. Короткое имя commit и одинаковое имя файла недостаточны: нужен тот же полный идентификатор. Чистый status тоже не доказывает push. Если ветка ведёт к версии позднее B3 или commit не совпадает с нужной основой, остановитесь и уточните, какую опубликованную версию следует получить.`}),(0,g.jsx)(a,{statement:`Если git status --short ничего не вывел, нужный commit точно опубликован в remote.`,isTrue:!1,explanation:`Status описывает файлы локальной папки. Для публикации отдельно сверяем remote, ветку и полный commit ID.`})]}),(0,g.jsxs)(i,{number:`04`,title:`Проверяем четыре договора на новых данных`,children:[(0,g.jsx)(`p`,{children:`Запуск в clone сам по себе не подтверждает все обязанности функций, поэтому после него мы наблюдаем их результаты. normalize_title убирает пробелы только с краёв, сохраняет регистр и пробелы внутри; пустой результат допустим. create_task получает уже подготовленные id, название и приоритет, создаёт отдельный словарь с is_done=False и не читает ввод, не выбирает id и не добавляет запись в список.`}),(0,g.jsx)(`p`,{children:`format_task возвращает строку карточки вида [id] title | приоритет: priority | состояние. Состояние равно выполнена или не завершена. Сама функция не печатает и не меняет словарь: печать результата относится к демо. calculate_study_minutes возвращает сумму переданного списка, для пустого списка это 0, и сохраняет входной список без изменений. Это учебная функция, не команда calc.`}),(0,g.jsx)(`p`,{children:`Возьмём новые значения. Несколько пробелов внутри названия помогут увидеть, что нормализация не сжимает их. Изменение первой записи покажет, осталась ли вторая независимой. Карточки проверим в двух состояниях, а сумму проследим на непустом и пустом списке. Нам нужен наблюдаемый ответ, а не только сообщение, что файл запустился.`}),(0,g.jsx)(h,{caption:`Независимая проверка договоров в компактном демо`,code:[`clean_title = normalize_title("  План   недели  ")`,`print(clean_title)`,`print(normalize_title("   ") == "")`,``,`first = create_task(17, clean_title, 2)`,`second = create_task(18, normalize_title("  Прочитать главу  "), 4)`,`second_title_before_first_change = second["title"]`,`first["title"] = "План изменён"`,`first["is_done"] = True`,`print(second["title"] == second_title_before_first_change)`,`first_before_format = first.copy()`,`second_before_format = second.copy()`,`first_card = format_task(first)`,`second_card = format_task(second)`,`print(first == first_before_format)`,`print(second == second_before_format)`,`print(first_card)`,`print(second_card)`,``,`durations = [35, 50]`,`print(calculate_study_minutes(durations))`,`print(durations)`,`print(calculate_study_minutes([]))`].join(`
`)}),(0,g.jsx)(`p`,{children:`Ожидаем: очищенное название сохраняет три внутренних пробела, пустая очистка сравнивается с пустой строкой, сравнение с названием второй записи, сохранённым до изменения первой, даёт True. После форматирования оба сравнения со снимками словарей тоже дают True. Карточки показывают «выполнена» и «не завершена». Сумма равна 85, список остаётся [35, 50], пустая сумма равна 0. Если наблюдение другое, найдём дефект в основной копии, а не будем маскировать его тестовыми данными.`})]}),(0,g.jsxs)(i,{number:`05`,title:`Публикуем исправление и обновляем копию`,children:[(0,g.jsx)(`p`,{children:`Если договор не выполнен или демо мешает увидеть результат, исправляем только основной проект. Сохраняем main.py, запускаем его знакомым Python 3.12 и читаем status и обычный diff. Если diff пуст, ничего не придумываем и не создаём пустой commit: сверяем полный SHA с опубликованной веткой. Чистое состояние файлов не заменяет эту сверку.`}),(0,g.jsx)(`p`,{children:`Если в diff есть нужная содержательная правка только в main.py, подготавливаем именно этот файл, просматриваем staged diff, затем создаём commit и отправляем его в тот же remote и ту же ветку. Не используем git add --all и не включаем случайные файлы. Push обновляет remote, но не перезаписывает уже созданный clone. После публикации возвращаемся в проверочную папку, проверяем её путь, origin, ветку и чистое состояние.`}),(0,g.jsx)(`p`,{children:`Обновляйте существующий clone командой git pull --ff-only origin "ИМЯ_ВЕТКИ", только если он чистый, origin указывает на выбранный remote, а имя текущей ветки совпадает с выбранной веткой. Подставьте точное имя из шага 02: явные origin и ветка показывают, откуда именно придут изменения. Когда clone стоит на A, а выбранная ветка remote продвинулась A→B, Git передвигает clone на B. Если в clone появился отдельный commit C от A, истории расходятся и fast-forward невозможен. После успешного обновления сверьте полный SHA и запустите main.py из clone.`}),(0,g.jsxs)(f,{caption:`Как git pull --ff-only обновляет проверочный clone`,orientation:`vertical`,children:[(0,g.jsxs)(u,{label:`Чистый clone можно передвинуть с A на B`,orientation:`vertical`,children:[(0,g.jsx)(c,{title:`Начало: clone и remote на A`,children:(0,g.jsx)(`p`,{children:`Обе ветки указывают на один commit`})}),(0,g.jsx)(l,{label:`в remote опубликован новый commit B`}),(0,g.jsx)(c,{title:`Remote: A → B`,children:(0,g.jsx)(`p`,{children:`Clone пока остаётся на A`})}),(0,g.jsx)(l,{label:`git pull --ff-only origin "ИМЯ_ВЕТКИ"`}),(0,g.jsx)(c,{title:`Clone передвинут на B`,children:(0,g.jsx)(`p`,{children:`Git сдвинул ветку clone по прямой истории`})})]}),(0,g.jsxs)(u,{label:`Отдельный commit в clone расходится с remote`,orientation:`vertical`,children:[(0,g.jsx)(c,{title:`Общее начало: A`,children:(0,g.jsx)(`p`,{children:`Clone и remote начинаются с одного commit`})}),(0,g.jsx)(l,{label:`в clone создан отдельный commit C`}),(0,g.jsx)(c,{title:`Clone: A → C`,children:(0,g.jsx)(`p`,{children:`Remote всё ещё начинается от A`})}),(0,g.jsx)(l,{label:`remote отдельно продвинут на B`}),(0,g.jsx)(c,{title:`Истории разошлись`,children:(0,g.jsx)(`p`,{children:`Clone: A → C; remote: A → B`})})]}),(0,g.jsx)(p,{title:`Почему команда остановится`,children:(0,g.jsx)(`p`,{children:`git pull --ff-only откажет: C не предок B. Git не создаст merge-commit и не передвинет clone через отдельную историю.`})})]}),(0,g.jsx)(`p`,{children:`При отказе проверьте обе истории и сохраните локальный commit до решения, как их согласовать. Не сбрасывайте clone вслепую. После прямого продвижения SHA clone должен совпасть с выбранным commit remote.`})]}),(0,g.jsxs)(i,{number:`06`,title:`Где заканчивается B3`,children:[(0,g.jsx)(`p`,{children:`Передаются четыре компонента: normalize_title, create_task, format_task и calculate_study_minutes, вместе с проектом и его историей. Следующий блок соберёт из них пользовательский Planner с запуском и списком задач. Здесь проверяем передачу проекта и не расширяем main.py этими операциями.`}),(0,g.jsx)(`p`,{children:`Передача подтверждена, когда clone совпал по полному SHA с выбранной веткой remote и все четыре функции прошли проверку. Дальше разработка продолжается в основном каталоге.`}),(0,g.jsx)(m,{question:`Своими словами назовите четыре готовых компонента B3 и два шага, которые отделяют рабочую правку от её появления в clone.`,hint:`Вспомните, что сначала сохраняет версию в локальной истории, а затем переносит её в выбранную ветку remote.`,answer:(0,g.jsx)(`p`,{children:`Готовы normalize_title, create_task, format_task и calculate_study_minutes. Чтобы правка появилась в clone, сначала создаём для неё локальный commit, затем публикуем его в нужную ветку. Clone получает опубликованную историю.`})})]}),(0,g.jsxs)(i,{number:`07`,title:`Что мы будем делать в практике`,children:[(0,g.jsx)(r,{children:`Мы пройдём весь путь передачи на одном собственном StudyHub, сохраняя основную папку и одну проверочную копию.`}),(0,g.jsx)(s,{variant:`connected`,items:[{title:`Подтвердим основу B3`,description:`Запишем свой remote, ветку, полный SHA и путь.`},{title:`Подготовим clone`,description:`Получим clone собственной опубликованной ветки в свободную соседнюю папку или проверим уже готовую копию.`},{title:`Проверим четыре договора`,description:`Запустим основной файл на новых данных и при необходимости исправим только основную версию.`},{title:`Опубликуем содержательное исправление`,description:`Создадим commit, только если исправление действительно есть; искусственный commit не понадобится.`},{title:`Передадим чистую версию`,description:`Обновим существующий clone, сравним commit, запустим main.py и назовём следующий шаг курса.`}]}),(0,g.jsx)(`p`,{children:`Передачу подтверждают путь clone, нужные origin и ветка, совпадающий полный SHA и запуск четырёх функций. Если источник или версия не совпадают, остановитесь с точной причиной; после проверки возвращайтесь к разработке в основном каталоге.`})]})]})}export{_ as Lesson15_1};